    "ce": "# Arrows that point at symbols — exported by Manim Formula Editor for ManimCE 0.22.\n# Render at 1920×1080, 60 fps:\n#     manim -r 1920,1080 --fps 60 ArrowsThatPointAtSymbols.py ArrowsThatPointAtSymbols\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 450 frames, like the editor's video export.\nfrom manim import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass ArrowsThatPointAtSymbols(Scene):\n    def construct(self):\n        self.camera.background_color = \"#000000\"\n\n        # equation: x = 5\n        equation = MathTex(r\"x = 5\", font_size=144)\n        equation_g = _glyphs(equation, [\n            (-1.3318, -0.1548, 0.7078, 0.6584), (0.064, -0.1047, 0.968, 0.3401), (1.3958, 0, 0.5799, 1),\n        ])\n        equation_g[0].set_color(\"#58C4DD\")\n        equation_g[2].set_color(\"#83C167\")\n\n        # l1: arrow, built on equation where its clip starts\n\n        # l2: arrow, built on equation where its clip starts\n\n        # 0 s – 1.2 s: equation write\n        self.play(Write(VGroup(*equation_g[:])), run_time=1.2)\n        # 1.2 s – 2 s\n        self.wait(0.8)\n        l1 = Arrow([-4.6, 2.4, 0], equation_g[0].get_corner(UL), color=\"#58C4DD\")\n        l1.set_z_index(1)\n        # 2 s – 2.9 s: l1 grow_arrow\n        self.play(GrowArrow(l1), run_time=0.9)\n        # 2.9 s – 3.2 s\n        self.wait(0.3)\n        l2 = Arrow([4.6, -2.4, 0], equation_g[2].get_corner(DR), color=\"#83C167\")\n        l2.set_z_index(2)\n        # 3.2 s – 4.1 s: l2 grow_arrow\n        self.play(GrowArrow(l2), run_time=0.9)\n        # 4.1 s – 6.9 s\n        self.wait(2.8)\n        # 6.9 s – 7.5 s: l1 fade_out, l2 fade_out, equation fade_out\n        self.play(FadeOut(l1), FadeOut(l2), FadeOut(equation), run_time=0.6)\n",
    "gl": "# Arrows that point at symbols — exported by Manim Formula Editor for ManimGL 1.7.\n# Render at 1920×1080, 60 fps:\n#     manimgl ArrowsThatPointAtSymbols.py ArrowsThatPointAtSymbols -w -r 1920x1080 --fps 60\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 450 frames, like the editor's video export.\nfrom manimlib import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass ArrowsThatPointAtSymbols(Scene):\n    default_camera_config = dict(background_color=\"#000000\")\n\n    def construct(self):\n\n        # equation: x = 5\n        equation = Tex(r\"x = 5\", font_size=148.4832)\n        equation_g = _glyphs(equation, [\n            (-1.3318, -0.1548, 0.7078, 0.6584), (0.064, -0.1047, 0.968, 0.3401), (1.3958, 0, 0.5799, 1),\n        ])\n        equation_g[0].set_color(\"#58C4DD\")\n        equation_g[2].set_color(\"#83C167\")\n\n        # l1: arrow, built on equation where its clip starts\n\n        # l2: arrow, built on equation where its clip starts\n\n        # 0 s – 1.2 s: equation write\n        self.play(Write(VGroup(*equation_g[:]), stroke_color=\"#FFFFFF\"), run_time=1.2)\n        # 1.2 s – 2 s\n        self.wait(0.8)\n        l1 = Line([-4.6, 2.4, 0], equation_g[0].get_corner(UL), buff=0.25, stroke_width=6, color=\"#58C4DD\").add_tip(length=0.35, width=0.35)\n        l1.set_z_index(1)\n        # 2 s – 2.9 s: l1 grow_arrow\n        self.play(GrowArrow(l1), run_time=0.9)\n        # 2.9 s – 3.2 s\n        self.wait(0.3)\n        l2 = Line([4.6, -2.4, 0], equation_g[2].get_corner(DR), buff=0.25, stroke_width=6, color=\"#83C167\").add_tip(length=0.35, width=0.35)\n        l2.set_z_index(2)\n        # 3.2 s – 4.1 s: l2 grow_arrow\n        self.play(GrowArrow(l2), run_time=0.9)\n        # 4.1 s – 6.9 s\n        self.wait(2.8)\n        # 6.9 s – 7.5 s: l1 fade_out, l2 fade_out, equation fade_out\n        self.play(FadeOut(l1), FadeOut(l2), FadeOut(equation), run_time=0.6)\n"
